use glam::DVec3;use ingetrazo_gui::{IngeTrazoApp,navigation::{self,Mode}};
fn frame(app:&mut IngeTrazoApp,ctx:&egui::Context,time:f64,events:Vec<egui::Event>){let _=ctx.run(egui::RawInput{screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(800.,600.))),time:Some(time),focused:true,events,..Default::default()},|ctx|{egui::CentralPanel::default().frame(egui::Frame::none()).show(ctx,|ui|{let rect=ui.available_rect_before_wrap();let response=ui.allocate_rect(rect,egui::Sense::click_and_drag());navigation::input(app,ui,rect,&response);});});}
fn button(pos:egui::Pos2,button:egui::PointerButton,pressed:bool)->egui::Event{egui::Event::PointerButton{pos,button,pressed,modifiers:egui::Modifiers::NONE}}
fn main(){let mut rows=vec![];for name in ["left-move-release","left-press-move-release","right-move-release","right-press-move-release","left-relative-move-release","right-relative-move-release","unrelated-release-retains-left","left-release-ends-with-right-held","unowned-relative-before-press"]{
let mut app=IngeTrazoApp::new();app.camera.distance=10.;app.camera.look_from(DVec3::new(0.,0.,1.68),DVec3::Y);app.activate_navigation(Mode::FirstPerson);let ctx=egui::Context::default();frame(&mut app,&ctx,0.,vec![]);let before=app.camera.eye();let a=egui::pos2(400.,300.);let b=egui::pos2(440.,260.);let selected=if name.starts_with("right"){egui::PointerButton::Secondary}else{egui::PointerButton::Primary};let press=vec![egui::Event::PointerMoved(a),button(a,selected,true)];let mut tail=vec![egui::Event::PointerMoved(b)];if name.starts_with("left-relative")||name.starts_with("right-relative"){tail.push(egui::Event::MouseMoved(egui::vec2(40.,-40.)));}tail.push(button(b,selected,false));
if name=="left-release-ends-with-right-held"{frame(&mut app,&ctx,0.01,press);frame(&mut app,&ctx,0.02,vec![button(a,egui::PointerButton::Secondary,true)]);frame(&mut app,&ctx,0.03,vec![button(a,egui::PointerButton::Primary,false),egui::Event::PointerMoved(b)]);frame(&mut app,&ctx,0.04,vec![button(b,egui::PointerButton::Secondary,false)]);}
else if name=="unowned-relative-before-press"{frame(&mut app,&ctx,0.01,std::iter::once(egui::Event::MouseMoved(egui::vec2(1000.,1000.))).chain(press).chain(tail).collect());}
else if name.contains("press-move"){frame(&mut app,&ctx,0.01,press.into_iter().chain(tail).collect());}
else{frame(&mut app,&ctx,0.01,press);if name=="unrelated-release-retains-left"{tail.insert(0,button(a,egui::PointerButton::Secondary,false));}frame(&mut app,&ctx,0.02,tail);}
rows.push(serde_json::json!({"name":name,"eye":app.camera.eye().to_array(),"before_eye":before.to_array(),"yaw":app.camera.yaw,"pitch":app.camera.pitch,"undo":app.undo_stack.len()}));}println!("{}",serde_json::json!({"cases":rows}));}
